from .aashell_rad_params import change_rad_param, create_swconfig_flag_address_list
from robot.api import logger
from .aashell_cell_mapping import get_cell_mapping
from .aashell import execute_aashell_command
import pprint


class ta5g_aashell(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @staticmethod
    def execute_aashell_command(command):
        """
        Execute a command in AaShell
        :param command: commande to execute
        :return: command output without AaShell prompt
        """
        return execute_aashell_command(command.encode('ascii'))

    @staticmethod
    def change_rad_param(param, value, is_permanent=True):
        """
        Changes RaD parameter online through AaShell permanently
        :param param: parameter to change in hex format (0x###)
        :param value: value of parameter
        :param is_permanent: is parameter change done permanently
        """
        change_rad_param(param, value, is_permanent)

    @staticmethod
    def get_cell_mapping_from_aashell(aashell_port='15007'):
        """
        Returns cell mapping from AaShell in dict format
        :param aashell_port: AaShell port (default 15007)
        :return: cell mapping as dict
        """
        return get_cell_mapping(aashell_port)

    @staticmethod
    def set_mo_flag_iphy_aashell(
        rrh_id, value, delay=0, mode=3, cell_class_id='Tx', iphy_ip='192.168.200.1', oam_term_port='8023', how_many='-1'
    ):

        """
        Execute set_mo_flag in iphy aashell cli
        set_mo_flag rrhid classId <1:create|2=update|3=both> [distName='' delay [OK=1|NOK=0]]
        :param rrh_id: iphy radio head id
        :param value: OK=1, NOK=0
        :param delay: after this time in ms RP1:modifyParameterResp will be send. [ms]
        :param mode: <1:create|2=update|3=both>
        :param cell_class_id: iphy cell class id [Tx, Rx]
        :param iphy_ip: iphy ip address
        :param how_many: how many massge should be delay or failed, -1 means infinity
        :param oam_term_port: iphy oam term port
        """

        set_mo_flag_iphy_cmd = 'set_mo_flag {rrh_id} {Tx_Rx} {mode} "" {delay} {value} {how_many}'
        cmd = set_mo_flag_iphy_cmd.format(
            rrh_id=rrh_id, Tx_Rx=cell_class_id, mode=mode, delay=delay, value=value, how_many=how_many
        )
        pprint.pprint(cmd)
        output = execute_aashell_command(cmd, iphy_ip, oam_term_port)
        if output == ' ':
            pass
        else:
            raise SetMoFlagIphyAashellFailed(output)

    @staticmethod
    def enable_debug_logs_in_runtime(sw_config_flags=None):
        """
        Sets RaD parameters to True from sw_config_flags online through AaShell
        :param sw_config_flags: list of RaD parameters to change in format [0x######a ...., 0x######b ...., n]
        """
        swconfig_flag_list = create_swconfig_flag_address_list(sw_config_flags)
        logger.warn('Enabling following R&D flags:{}'.format(swconfig_flag_list))
        for rnd_param in swconfig_flag_list:
            change_rad_param(param=rnd_param, value=1, is_permanent=False)

    @staticmethod
    def disable_debug_logs_in_runtime(sw_config_flags=None):
        """
        Sets RaD parameters to False from sw_config_flags online through AaShell
        :param sw_config_flags: list of RaD parameters to change in format [0x######a ...., 0x######b ...., n]
        """
        swconfig_flag_list = create_swconfig_flag_address_list(sw_config_flags)
        logger.warn('Disabling following R&D flags:{}'.format(swconfig_flag_list))
        for rnd_param in swconfig_flag_list:
            change_rad_param(param=rnd_param, value=0, is_permanent=False)


class SetMoFlagIphyAashellFailed(Exception):
    def __init__(self, output):
        Exception.__init__(self)
        self.value = 'Problem with execute iphy aashell cmd, output: {}'.format(output)

    def __str__(self):
        return repr(self.value)
